import Cycles "mo:base/ExperimentalCycles";
import Principal "mo:base/Principal";
import NFTActorClass "../NFT/nft";

persistent actor OpenD {

  public shared (msg) func mint(imgData : [Nat8], name : Text) : async Principal {
    let owner : Principal = msg.caller;
    Cycles.add(1_200_000_000_000);
    let newNFT = await NFTActorClass.NFT(name, owner, imgData);
    let newNFTPrincipal = await newNFT.getCanisterId();
    return newNFTPrincipal;
  };
};

import Principal "mo:base/Principal";

persistent actor class NFT(name : Text, owner : Principal, content : [Nat8]) = this {
  let itemName = name;
  let nftOwner = owner;
  let imageBytes = content;

  public query func getName() : async Text { return itemName; };
  public query func getOwner() : async Principal { return nftOwner; };
  public query func getAsset() : async [Nat8] { return imageBytes; };

  // "= this" binds the class instance so it can report its own canister id
  public query func getCanisterId() : async Principal {
    return Principal.fromActor(this);
  };
};

import React, { useState } from "react";
import { useForm } from "react-hook-form";
import { OPEND_backend } from "../../../declarations/OPEND_backend";
import Item from "./Item";

function Minter() {
  const { register, handleSubmit } = useForm();
  const [nftPrincipal, setNFTPrincipal] = useState("");
  const [loaderHidden, setLoaderHidden] = useState(true);

  async function onSubmit(data) {
    setLoaderHidden(false);
    const name = data.name;
    const image = data.image[0];               // FileList -> first File
    const imageArray = await image.arrayBuffer();
    const imageByteData = [...new Uint8Array(imageArray)]; // plain number[] -> [Nat8]
    const newNFTId = await OPEND_backend.mint(imageByteData, name);
    setNFTPrincipal(newNFTId);
    setLoaderHidden(true);
  }

  if (nftPrincipal == "") {
    return (
      <div className="minter-container">
        <div hidden={loaderHidden} className="lds-ellipsis">
          <div></div><div></div><div></div><div></div>
        </div>
        <h3>Create NFT</h3>
        <form>
          <input {...register("image", { required: true })} className="upload" type="file" accept="image/x-png,image/jpeg,image/gif,image/svg+xml,image/webp" />
          <input {...register("name", { required: true })} placeholder="e.g. CryptoDunks" type="text" />
          <span onClick={handleSubmit(onSubmit)} className="form-Chip-label">Mint NFT</span>
        </form>
      </div>
    );
  } else {
    return (
      <div className="minter-container">
        <h3>Minted!</h3>
        <div className="horizontal-center">
          <Item id={nftPrincipal.toText()} />
        </div>
      </div>
    );
  }
}
export default Minter;

